	/**
	 * Default Constructor
	 */
    public WorkShiftService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new WorkShiftEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(WorkShiftRepository.class) );
		this.validator		= applicationContext.getBean(WorkShiftValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		WorkShift
	 */
		public WorkShift createWorkShift( CreateWorkShiftCommand command ) {

		WorkShift entity = new WorkShift();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setWorkShiftId( command.getWorkShiftId() );
            entity.setStartTime( command.getStartTime() );
            entity.setEndTime( command.getEndTime() );
            entity.setBreakMinutes( command.getBreakMinutes() );
            entity.setDayOfWeek( command.getDayOfWeek() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of WorkShift {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateWorkShiftCommand
	 * @return		WorkShift
	 */
	public WorkShift updateWorkShift( UpdateWorkShiftCommand command ) {

		WorkShift entity = new WorkShift();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setWorkShiftId( command.getWorkShiftId() );
            entity.setStartTime( command.getStartTime() );
            entity.setEndTime( command.getEndTime() );
            entity.setBreakMinutes( command.getBreakMinutes() );
            entity.setWorkSchedule( command.getWorkSchedule() );
            entity.setDayOfWeek( command.getDayOfWeek() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of WorkShift {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteWorkShiftCommand
	 */
	public void delete( DeleteWorkShiftCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getWorkShiftId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of WorkShift {0} ", id );

	}

	/**
	 * Method to retrieve the WorkShift via WorkShiftFetchOneSummary
	 * @param 	summary WorkShiftFetchOneSummary
	 * @return 	WorkShiftFetchOneResponse
	 */
	public WorkShift getWorkShift( WorkShiftFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "WorkShiftFetchOneSummary arg cannot be null" );

		WorkShift entity = null;
		UUID id = summary.getWorkShiftId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a WorkShift using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all WorkShifts
	 *
	 * @return 	List<WorkShift>
	 */
    public List<WorkShift> getAllWorkShift() {
		List<WorkShift> list = projector.findAll( new FindAllWorkShiftQuery() );
		return list;
	}

	/**
	 * assign WorkSchedule on WorkShift
	 * @param		command AssignWorkScheduleToWorkShiftCommand
	 */
	public void assignWorkSchedule( AssignWorkScheduleToWorkShiftCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignWorkSchedule(command.getWorkShiftId(), command.getAssignment());

	}

	/**
	 * unAssign WorkSchedule on WorkShift
	 * @param		command UnAssignWorkScheduleFromWorkShiftCommand
	 */
	public void unAssignWorkSchedule( UnAssignWorkScheduleFromWorkShiftCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignWorkSchedule(command.getWorkShiftId());
	}
	




